starter.css:
.track-design { --track: oklch(62% 0.19 350); }

.session-card {
  margin-block-end: 12px;
  padding: 12px 16px;
  border-radius: 12px;
  border-inline-start: 6px solid var(--track, #94a3b8);
}
.session-card h3 { margin: 0 0 8px; }
.badge {
  display: inline-block;
  padding: 0.1em 0.6em;
  border-radius: 999px;
}

/* Hand-picked values: replace them with rules derived from --track */
.badge { background: #fce7f3; }
.session-card.is-active { border-inline-start-color: #9d174d; }

